{
  "findings": [
    {
      "check_id": "CKV_AZURE_115",
      "title": "Function App should use HTTPS-only",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "HIGH",
      "explanation": "The Function App does not enforce HTTPS-only traffic. This can expose sensitive data to interception over unencrypted HTTP connections."
    },
    {
      "check_id": "CKV_AZURE_116",
      "title": "Storage account access key should not be hardcoded",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "HIGH",
      "explanation": "The Function App is configured with a hardcoded storage account access key. This is a security risk as it can lead to unauthorized access if the key is exposed."
    }
  ],
  "patched_code": "resource "azurerm_linux_function_app" "alert_function" {
  name                = "smart-manufacturing-iot-monitoring-platform-function-app-alerts"
  resource_group_name = azurerm_resource_group.smart_manufacturing.name
  location            = azurerm_resource_group.smart_manufacturing.location
  service_plan_id     = azurerm_service_plan.dashboard_plan.id
  storage_account_name       = azurerm_storage_account.function_storage.name
  storage_account_access_key = var.storage_account_access_key

  site_config {
    application_stack {
      node_version = "18"
    }
    https_only = true
  }

  app_settings = {
    "FUNCTIONS_WORKER_RUNTIME" = "node"
  }
}

variable "storage_account_access_key" {
  description = "The access key for the storage account used by the Function App."
  type        = string
  sensitive   = true
}",
  "fix_summary": "Enabled HTTPS-only traffic for the Function App to enforce secure communication. Replaced the hardcoded storage account access key with a variable to avoid exposing sensitive information in the code."
}
